def change_base(x: int, base: int) -> str:
    if base < 2 or base > 9:
        raise ValueError("Base must be between 2 and 9")

    if x == 0:
        return '0'

    result = ''
    while x > 0:
        remainder = x % base
        if remainder < 10:
            result = str(remainder) + result
        else:
            result = chr(remainder + 55) + result  # Convert to letters a-z
        x = x // base

    return result
```

