        raise ValueError("Input must be a non-negative integer.")
    tri_sequence = [3]  # Base case for n=1
    if n > 1:
        tri_sequence.append(1)  # Base case for n=2
    for i in range(3, n + 1):
        if i % 2 == 0:
            tri_sequence.append(1 + i // 2)  # Even index
        else:
            tri_sequence.append(tri_sequence[i - 1] + tri_sequence[i - 2] + tri_sequence[i + 1])  # Odd index
    return tri_sequence[:n + 1]
